head.script:
scwin.__isCheck = function() {
    return WebSquare.logger.getErrorLog() == "";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 'name1'항목의 row('1')값을 클릭한다.
    //1. After executing the main sample, click the row ('1') value of 'name1' item. 
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. data:dataList1.col1값에 gridView에서 선택한 '1'값이 입력되어 보여진다. (이전에는 선택값이 입력되지 않음)
    //1. data: dataList1.col1 value is displayed with '1' value selected in gridView. (Previously no selection value entered)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'udc_test11_input1').value", "1");
    WebSquare.wUnit.addCommand("pause", "500");
    //2. The normal log is displayed. (Previously there was an error related to Exception Occur at element id [dataList1])
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.json1 = [{
            "col1": "1",
            "col2": "2",
            "col3": "3"
        },
        {
            "col1": "4",
            "col2": "5",
            "col3": "6"
        }
    ];
    dataList1.setJSON(window.json1);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 17-July-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
